r.append(R(6615019,"आम और टमाटर की सालसा के साथ ग्रिल्ड सैल्मन",
"आम और अन्य फल किसी भी सालसा में हल्की मिठास जोड़ सकते हैं। यह थोड़े तीखे सैल्मन व्यंजन के साथ ख़ास तौर पर अच्छा लगता है। सैल्मन के फिले को त्वचा सहित ग्रिल करने से उन्हें पलटना आसान होता है और वे चिपकते नहीं। ग्रिल की जाली पर तेल लगाने से भी चिपकना रोका जा सकता है: एक गोल मुड़े हुए पेपर टॉवल को तेल में डुबोएँ और साफ़ ग्रिल की जाली पर हल्के से रगड़ें।\n\nआप सैल्मन को ओवन में भी पका सकते हैं: ओवन को 425°F पर पहले से गरम करें और सैल्मन को एक उथले बेकिंग पैन में लगभग 10 मिनट तक बेक करें, या जब तक वह अंदर तक पक न जाए।",
"6","1 सैल्मन फिले (4 औंस) और 1/2 कप सालसा",
["1 बड़ा चम्मच चिली पाउडर","1 बड़ा चम्मच जीरा","1/4 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच पिसी दालचीनी","1/4 छोटा चम्मच नमक","1 1/2 पाउंड सैल्मन (त्वचा सहित, 6 फिले (हर एक 4 औंस) में कटा हुआ)","1 बड़ा चम्मच कैनोला तेल","1 1/2 कप आम (छोटे टुकड़ों में कटा)","1 1/2 कप टमाटर (छोटे टुकड़ों में कटे)","2 बड़े चम्मच नींबू का रस (बाँटकर इस्तेमाल करें)","1/2 कप हरा धनिया (कटा हुआ)"],
["ग्रिल को मध्यम-तेज़ आँच पर पहले से गरम करें।","एक छोटे कटोरे में चिली पाउडर, जीरा, लहसुन पाउडर, दालचीनी और नमक मिलाएँ। मसाले का मिश्रण सैल्मन के फिले पर समान रूप से छिड़कें।","कैनोला तेल से ग्रिल की जाली पर हल्का तेल लगाएँ। सैल्मन को त्वचा वाली तरफ़ नीचे रखकर ग्रिल पर रखें। बिना ढके 7 से 8 मिनट पकाएँ, बीच में एक बार पलट दें। सैल्मन तब तैयार है जब वह काँटे से आसानी से टूटने लगे।","सैल्मन पकते समय, एक मध्यम कटोरे में आम, टमाटर, हरा धनिया और आधा नींबू का रस मिलाएँ।","सैल्मन को ग्रिल से उतारें और बचा हुआ नींबू का रस छिड़कें। हर फिले को 1/2 कप सालसा के साथ परोसें।"]))
r.append(R(6618132,"किफ़ायती भूमध्यसागरीय मछली का स्टू",
"इस भूमध्यसागरीय मछली के स्टू की 4 सर्विंग्स की लागत 10 डॉलर से थोड़ी ही ज़्यादा है, लेकिन यह सचमुच एक खास व्यंजन बन सकता है और ठंडी सर्दियों के मौसम के लिए बेहतरीन है!",
"4","लगभग 1 ½ कप",
["1 बड़ा चम्मच ज़ैतून का तेल","1 मध्यम प्याज़ (कटा हुआ)","1 मध्यम लाल शिमला मिर्च (बीज निकालकर कटी हुई)","2 डंठल अजवाइन (सेलरी) (कटे हुए)","2 फांक लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच तुलसी (सूखी)","1 छोटा चम्मच सूखा ओरेगैनो (सूखा)","1 (28 औंस का डिब्बा) कुचले हुए टमाटर (बिना नमक मिलाए)","2 कप कम सोडियम वाला सब्ज़ियों का ब्रॉथ","6 औंस कॉड मछली के फिले (1 इंच के टुकड़ों में कटे)","6 औंस मध्यम आकार के झींगे (छिले, नस निकाली हुई, कटे हुए)","1/2 छोटा चम्मच काली मिर्च"],
["एक सूप के बर्तन में मध्यम आँच पर ज़ैतून का तेल डालें। प्याज़, शिमला मिर्च, अजवाइन, लहसुन, तुलसी और ओरेगैनो डालें। प्याज़ के पारदर्शी होने तक भूनें।","कुचले हुए टमाटर और सब्ज़ियों का ब्रॉथ डालें। उबाल आने दें, फिर आँच धीमी करके 10 मिनट उबलने दें, या जब तक सब्ज़ियाँ नरम न हो जाएँ।","कॉड और झींगे धीरे से मिलाएँ और 5 मिनट पकाएँ, या जब तक समुद्री भोजन अंदर तक न पक जाए।"]))
r.append(R(6618374,"मिनेस्ट्रोन पास्ता बाउल",
"यह वीगन, शाकाहारी और कम वसा वाली रेसिपी है। क्या आप भूमध्यसागरीय स्वाद से भरपूर, पेट भरने वाले पौधों पर आधारित लंच के लिए तैयार हैं? चने के पास्ता का यह बाउल रंग-बिरंगी सब्ज़ियों, काबुली चने और स्वादिष्ट जड़ी-बूटियों व मसालों से भरा है। यह आसान, सेहतमंद और पेट भरने वाला लंच आइडिया है।",
"6","1 कप",
["2 छोटे चम्मच एक्स्ट्रा वर्जिन ज़ैतून का तेल","1/2 पूरा पीला प्याज़ (कटा हुआ)","1 कप गाजर (छोटे टुकड़ों में कटी)","2 फांक लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच सूखी तुलसी","1/2 छोटा चम्मच सूखा ओरेगैनो","1 (14.5 औंस) डिब्बा कटे हुए टमाटर (बिना नमक मिलाए)","1 (16 औंस) डिब्बा डिब्बाबंद काबुली चना (कम सोडियम वाला, धोकर निथारा हुआ)","1/4 कप व्हाइट वाइन विनेगर","2 कप सब्ज़ियों का ब्रॉथ","4 औंस का डिब्बा चने के आटे का पेने पास्ता (लगभग 2 कप)","2 कप केल (डंठल निकालकर कटी हुई)"],
["एक बड़े सॉते पैन में मध्यम आँच पर ज़ैतून का तेल गरम करें। प्याज़ और गाजर डालें और नरम होना शुरू होने तक भूनें, लगभग 4 मिनट।","लहसुन डालकर 1 मिनट और भूनें, ध्यान रखें कि वह जले नहीं।","सूखे मसाले डालकर सब्ज़ियों पर लपेट दें। टमाटर, काबुली चना, व्हाइट वाइन विनेगर और ब्रॉथ डालें।","पास्ता डालकर अच्छी तरह चलाएँ। पैन को ढक दें और 6–7 मिनट पकने दें, जब तक पास्ता नरम होना शुरू न हो जाए।","केल डालें और 2 मिनट और पकाएँ, बस इतनी देर कि केल मुरझा जाए और पास्ता पूरी तरह पक जाए।"]))
r.append(R(6619453,"शिमला मिर्च और प्याज़ के साथ शीट पैन चीज़ी मिनी मीटलोफ",
"शिमला मिर्च और प्याज़ के रंग-बिरंगे मेल से बने इन शीट पैन चीज़ी मिनी मीटलोफ से अपने सप्ताह के डिनर को ख़ास बनाएँ। यह बहुत कम कार्बोहाइड्रेट वाले भोजन पैटर्न की रेसिपी न सिर्फ़ बनाने में आसान है, बल्कि स्वाद और पोषक तत्वों से भी भरपूर है, जो इसे पूरे परिवार को पसंद आने वाले सेहतमंद और संतोषजनक डिनर के लिए एकदम सही विकल्प बनाती है।",
"4","3 मीटलोफ, ½ कप सब्ज़ियाँ",
["1 पाउंड वसा रहित टर्की कीमा","1 पूरा अंडा","1/2 कप पैंको ब्रेड क्रम्ब्स","2 छोटे चम्मच इटैलियन सीज़निंग (बाँटकर)","1/2 छोटा चम्मच काली मिर्च","2 पूरी हरी शिमला मिर्च (कटी हुई)","1 मध्यम लाल प्याज़ (कटा हुआ)","2 बड़े चम्मच ज़ैतून का तेल","6 औंस का वसा रहित मोत्ज़ारेला चीज़ का ब्लॉक (12 स्लाइस में कटा हुआ)"],
["ओवन को 450 डिग्री F पर पहले से गरम करें। एक बड़ी बेकिंग शीट पैन पर एल्युमिनियम फ़ॉइल बिछाएँ।","टर्की, अंडा, ब्रेड क्रम्ब्स, आधी इटैलियन सीज़निंग और काली मिर्च को एक मध्यम कटोरे में डालें। हाथों से तब तक मिलाएँ जब तक मीटलोफ का मिश्रण अच्छी तरह मिल न जाए।","मिश्रण को लगभग 3 इंच लंबे 12 छोटे बेलनाकार टुकड़ों का आकार दें। इन्हें बेकिंग शीट के आधे हिस्से पर रखें।","शिमला मिर्च और प्याज़ को बेकिंग शीट के खाली हिस्से पर फैलाएँ। सब्ज़ियों पर तेल डालें, बची हुई सीज़निंग छिड़कें और अच्छी तरह मिलाएँ ताकि सब पर समान रूप से लग जाए। उन्हें एक परत में सजाएँ।","बेकिंग शीट को ओवन में रखें और भूनें, बीच में सब्ज़ियों को चलाएँ, जब तक मीटलोफ लगभग पक न जाएँ और काँटे से चुभोने पर सब्ज़ियाँ नरम न हों, लगभग 15–20 मिनट।","जब मीटलोफ लगभग तैयार हों तब बेकिंग शीट को ओवन से निकालें। हर मीटलोफ के ऊपर चीज़ के स्लाइस रखें। शीट को वापस ओवन में रखें और तब तक बेक करें जब तक मीटलोफ पूरी तरह पक न जाएँ और चीज़ पिघल न जाए, लगभग 2–3 मिनट और।"]))
r.append(R(6621202,"पैन में भुनी पैड्रॉन मिर्चें नमक के साथ",
"नमक के साथ पैन में भुनी पैड्रॉन मिर्चें एक सरल और मनभावन व्यंजन है जो पैड्रॉन मिर्चों के अनोखे स्वाद को उभारता है। ये छोटी हरी मिर्चें अपने हल्के, थोड़े मीठे स्वाद के लिए जानी जाती हैं, जिनमें कभी-कभार तीखापन भी मिल जाता है।",
"4","2 औंस मिर्चें",
["8 औंस पैड्रॉन मिर्चें","2 बड़े चम्मच ज़ैतून का तेल","1/4 छोटा चम्मच समुद्री नमक (परतदार)"],
["एक बड़े, भारी स्किलेट या फ्राइंग पैन को मध्यम-तेज़ आँच पर गरम करें। अपनी पसंद और स्किलेट के आकार के अनुसार 1–2 बड़े चम्मच ज़ैतून का तेल डालें।","जब तेल गरम होकर चमकने लगे, तो पैड्रॉन मिर्चें स्किलेट में डालें। आप इन्हें डंठल सहित साबुत रख सकते हैं। मिर्चों को बिना हिलाए लगभग 3–5 मिनट पकने दें, या जब तक उन पर फफोले पड़कर वे हल्की जल न जाएँ। चिमटे से बीच-बीच में पलटते रहें ताकि वे बराबर पकें।","जब पैड्रॉन मिर्चें नरम हो जाएँ, उन पर फफोले पड़ जाएँ और वे हल्की जल जाएँ, तो उन्हें स्किलेट से निकालकर परोसने की प्लेट में रखें।","मिर्चों के गरम रहते ही उन पर दरदरा समुद्री नमक भरपूर छिड़कें।"]))
r.append(R(6624712,"साबुत गेहूँ का डिनर रोल",
"साबुत गेहूँ के डिनर रोल की पोषण संबंधी जानकारी",
"1","1 औंस",
["1 औंस साबुत गेहूँ का डिनर रोल"],[]))
r.append(R(6625029,"बकरी के चीज़ और चुकंदर के साथ पालक सलाद",
"बकरी के चीज़ और चुकंदर वाला यह क्लासिक पालक सलाद रंग-बिरंगा, स्वादिष्ट और पोषक तत्वों से भरपूर है। पालक इसका सितारा है, विटामिन से भरी सब्ज़ी जो मधुमेह के अनुकूल किसी भी आहार में बढ़िया जोड़ है। शहद और डिजॉन सरसों की ड्रेसिंग थोड़ी मिठास जोड़ती है और इन स्वादों को अगले स्तर पर ले जाती है। अपने आहार में और पालक शामिल करना चाहते हैं? ये रेसिपी आज़माएँ! • आसान पालक रिकोटा एंचिलाडास • पालक आर्टिचोक भरे पोर्टोबेलो",
"6","2 कप",
["1 पाउंड चुकंदर (ऊपर के हरे पत्ते कटे हुए)","2 बड़े चम्मच कैनोला तेल","3 बड़े चम्मच पानी","2 छोटे चम्मच शहद","2 छोटे चम्मच डिजॉन सरसों","10 औंस बेबी पालक","1 1/2 औंस बकरी का चीज़ (चूरा किया हुआ)","1/4 कप चिलगोज़े (पाइन नट्स)"],
["चुकंदर को रगड़कर धोएँ, ऊपर के हरे पत्ते काटकर फेंक दें। इन्हें सॉसपैन या बर्तन में रखें और पानी से ढक दें। उबाल आने दें, फिर आँच धीमी करें और काँटे से आसानी से चुभने तक उबालें, 30–45 मिनट।","पानी से निकालकर ठंडा होने दें, फिर छीलें और फांकों में काट लें।","एक बड़े कटोरे में कैनोला तेल, पानी, शहद और डिजॉन सरसों को फेंटकर मिलाएँ। पालक डालें और अच्छी तरह मिलाएँ ताकि सब पर लग जाए।","चुकंदर, बकरी का चीज़ और चिलगोज़े डालें। फिर से हल्के हाथ से मिलाएँ।"]))
r.append(R(6625864,"देहाती क्राउटन्स के साथ सीज़र-शैली का सलाद",
"सीज़र सलाद किसे पसंद नहीं? यह सलाद बिना स्टार्च वाली सब्ज़ियों की एक बढ़िया साइड डिश है जिसका आनंद आप लगभग किसी भी मुख्य व्यंजन के साथ ले सकते हैं!",
"4","1 कप सलाद + 2 बड़े चम्मच ड्रेसिंग + 1/2 कप क्राउटन्स",
["2 स्लाइस साबुत गेहूँ की ब्रेड या फ्रेंच ब्रेड (1/2 इंच के टुकड़ों में फाड़ी हुई)","1/8 छोटा चम्मच लहसुन पाउडर","2 बड़े चम्मच कम वसा वाली मेयोनेज़","1/2 कप वसा रहित या कम वसा वाली छाछ (बटरमिल्क)","1 1/2 बड़े चम्मच पार्मेसन चीज़ (कद्दूकस किया हुआ)","4 कप पैकेट में बंद मिली-जुली हरी पत्तेदार सब्ज़ियाँ"],
["ओवन को 350 डिग्री F पर पहले से गरम करें।","एक छोटे कटोरे में छाछ, मेयोनेज़, लहसुन पाउडर, नमक (वैकल्पिक) और काली मिर्च (वैकल्पिक) स्वादानुसार फेंटकर मिलाएँ। प्लास्टिक रैप से ढककर कम से कम 1 घंटे फ्रिज में रखें ताकि वह थोड़ा गाढ़ा हो जाए।","इस बीच, ब्रेड के टुकड़े बेकिंग शीट पर रखें और 8 मिनट बेक करें, या जब तक वे थोड़े सख़्त न हो जाएँ। आँच से उतारकर थोड़ा ठंडा होने दें।","मिली-जुली हरी पत्तेदार सब्ज़ियाँ सलाद के कटोरे में रखें, ड्रेसिंग और चीज़ डालें और हल्के हाथ से लेकिन अच्छी तरह मिलाएँ ताकि सब पर लग जाए। चाहें तो ऊपर से हल्का नमक और काली मिर्च डालें। क्राउटन्स डालें, हल्के से मिलाएँ और तुरंत परोसें।","*नोट: वैकल्पिक नमक और काली मिर्च ऊपर दी गई पोषण संबंधी जानकारी में शामिल नहीं हैं।"]))
save(2,r)
